def _to_numeric_coord(value: Any) -> float | int:
    """Convert a coordinate value to a numeric value for range comparisons.

    Handles numbers, ISO datetime strings, naive datetimes, and timezone-aware
    datetimes. Naive datetimes are treated as UTC, so a naive datetime, a
    UTC-aware datetime, and a UTC ISO string that denote the same instant all
    produce the same numeric value, independent of the system timezone.
    """
    import datetime

    # bool is a subclass of int; normalize before the int/float check.
    if isinstance(value, bool):
        return int(value)

    if isinstance(value, (int, float)):
        return value

    parsed: Any = value
    if isinstance(value, str):
        parsed = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))

    if isinstance(parsed, datetime.datetime):
        # Treat naive datetimes as UTC so the numeric value is independent of
        # the system timezone.
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime.timezone.utc)
        return parsed.timestamp()

    if isinstance(parsed, datetime.date):
        dt = datetime.datetime(
            parsed.year,
            parsed.month,
            parsed.day,
            tzinfo=datetime.timezone.utc,
        )
        return dt.timestamp()

    return float(parsed)


def _bar_value_in_selection_range(
    trace: Any,
    point_idx: int,
    point_value: Any,
    selection_min: float,
    selection_max: float,
) -> bool:
    """Check whether a bar's value extent overlaps the selection range.

    A bar spans from its base (default 0) to ``base + value`` on the value axis.
    Returns ``False`` without raising when the point value or the trace base are
    non-numeric (e.g. category strings sent from the frontend).
    """
    base = getattr(trace, "base", None)

    if isinstance(base, str):
        return False

    if base is None:
        base_val: Any = 0
    elif hasattr(base, "__len__"):
        try:
            base_val = base[point_idx]
        except (IndexError, KeyError, TypeError):
            base_val = 0
    else:
        base_val = base

    if isinstance(point_value, str) or isinstance(base_val, str):
        return False

    try:
        value_num = float(point_value)
        base_num = float(base_val)
    except (TypeError, ValueError):
        return False

    bar_low = min(base_num, base_num + value_num)
    bar_high = max(base_num, base_num + value_num)

    return not (selection_max < bar_low or selection_min > bar_high)


def _axis_field_names(figure: go.Figure) -> tuple[str, str]:
    """Return the (x, y) field names to use for selected point dicts.

    Uses single-axis titles when available, falling back to "x"/"y".
    """
    x_axes: list[Any] = []
    figure.for_each_xaxis(x_axes.append)
    x_axis = x_axes[0] if len(x_axes) == 1 else None

    y_axes: list[Any] = []
    figure.for_each_yaxis(y_axes.append)
    y_axis = y_axes[0] if len(y_axes) == 1 else None

    x_field = x_axis.title.text if (x_axis and x_axis.title.text) else "x"
    y_field = y_axis.title.text if (y_axis and y_axis.title.text) else "y"
    return x_field, y_field


def _category_positions(data: Any) -> dict[Any, int]:
    """Map category labels to integer positions.

    Repeated category values share the same position, matching how Plotly lays
    out categorical axes.
    """
    return {value: idx for idx, value in enumerate(dict.fromkeys(data))}


def _axis_is_orderable(data: Any, bound_value: Any) -> bool:
    """Whether an axis's values can be compared directly with the bounds.

    Uses numpy dtype inspection when numpy is available, otherwise inspects the
    first element. Both numpy and fallback extraction paths call this so that
    they make identical orderable-vs-categorical decisions.
    """
    if DependencyManager.numpy.has():
        import numpy as np

        return _is_orderable_axis(np.asarray(data), bound_value)

    if not _is_orderable_value(bound_value):
        return False
    for value in data:
        return _is_orderable_value(value)
    return False


def _point_in_polygon(
    x: float, y: float, polygon: list[tuple[float, float]]
) -> bool:
    """Ray-casting point-in-polygon test on numeric coordinates."""
    inside = False
    n = len(polygon)
    if n < 3:
        return False
    j = n - 1
    for i in range(n):
        xi, yi = polygon[i]
        xj, yj = polygon[j]
        if ((yi > y) != (yj > y)) and (
            x < (xj - xi) * (y - yi) / (yj - yi) + xi
        ):
            inside = not inside
        j = i
    return inside


